import com.sun.net.httpserver.HttpExchange; import java.io.IOException; import java.io.OutputStream; import java.nio.charset.StandardCharsets; import java.util.ArrayList; import java.util.Collections; import java.util.Comparator; import java.util.LinkedHashMap; import java.util.List; import java.util.Map; final class OverviewHandler { private OverviewHandler() {} static void handle(HttpExchange ex, StatsStore store) throws IOException { List<StatsStore.Dev> devs = store.devices(); List<StatsStore.Use> uses = store.usage(); long totalDevices = devs.size(); long totalSeconds = 0; for (StatsStore.Dev d : devs) totalSeconds += d.totalSeconds(); Map<String, long[]> dailyAgg = new LinkedHashMap<>(); for (StatsStore.Use u : uses) { long[] agg = dailyAgg.get(u.date()); if (agg == null) { agg = new long[2]; dailyAgg.put(u.date(), agg); } agg[0]++; agg[1] += u.seconds(); } List<String> dates = new ArrayList<>(dailyAgg.keySet()); dates.sort(Collections.reverseOrder()); if (dates.size() > 30) dates = dates.subList(0, 30); List<StatsStore.Dev> sorted = new ArrayList<>(devs); sorted.sort(new Comparator<StatsStore.Dev>() { public int compare(StatsStore.Dev a, StatsStore.Dev b) { return b.lastSeen().compareTo(a.lastSeen()); } }); if (sorted.size() > 50) sorted = sorted.subList(0, 50); StringBuilder b = new StringBuilder(); b.append('{'); b.append(q("totalDevices")).append(':').append(totalDevices); b.append(',').append(q("totalSeconds")).append(':').append(totalSeconds); b.append(',').append(q("daily")).append(':').append('['); for (int i = 0; i < dates.size(); i++) { if (i > 0) b.append(','); String date = dates.get(i); long[] agg = dailyAgg.get(date); b.append('{').append(q("date")).append(':').append(q(date)); b.append(',').append(q("devices")).append(':').append(agg[0]); b.append(',').append(q("seconds")).append(':').append(agg[1]).append('}'); } b.append(']'); b.append(',').append(q("recent")).append(':').append('['); for (int i = 0; i < sorted.size(); i++) { if (i > 0) b.append(','); StatsStore.Dev d = sorted.get(i); b.append('{').append(q("deviceId")).append(':').append(q(d.deviceId())); b.append(',').append(q("os")).append(':').append(q(d.os())); b.append(',').append(q("appVersion")).append(':').append(q(d.appVersion())); b.append(',').append(q("lastIp")).append(':').append(q(d.lastIp())); b.append(',').append(q("firstSeen")).append(':').append(q(d.firstSeen())); b.append(',').append(q("lastSeen")).append(':').append(q(d.lastSeen())); b.append(',').append(q("reportCnt")).append(':').append(d.reportCnt()); b.append(',').append(q("totalSeconds")).append(':').append(d.totalSeconds()); b.append('}'); } b.append(']'); b.append('}'); send(ex, 200, b.toString()); } private static String q(String s) { if (s == null) s = ""; StringBuilder sb = new StringBuilder(); sb.append((char) 34); for (int i = 0; i < s.length(); i++) { char c = s.charAt(i); if (c == 34) { sb.append((char) 92).append((char) 34); } else if (c == 92) { sb.append((char) 92).append((char) 92); } else if (c == 10) { sb.append((char) 92).append('n'); } else if (c == 13) { sb.append((char) 92).append('r'); } else if (c == 9) { sb.append((char) 92).append('t'); } else if (c < 32) { sb.append('?'); } else { sb.append(c); } } sb.append((char) 34); return sb.toString(); } private static void send(HttpExchange ex, int code, String body) throws IOException { byte[] bytes = body.getBytes(StandardCharsets.UTF_8); ex.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8"); ex.getResponseHeaders().set("Server", "gairr-stats-server-java"); ex.sendResponseHeaders(code, bytes.length); try (OutputStream os = ex.getResponseBody()) { os.write(bytes); } } }